"""Independent audit: rotations generated by quarter-turn closure, not signed permutations."""
from pathlib import Path
from itertools import product
from collections import deque
import hashlib,json
from puzzles import QUESTIONS

ROOT=Path(__file__).resolve().parent

def norm(shape):
    a=tuple(map(tuple,shape));lo=tuple(min(p[i] for p in a) for i in range(3))
    return tuple(sorted(tuple(p[i]-lo[i] for i in range(3)) for p in a))

def mx(v):x,y,z=v;return (x,-z,y)
def my(v):x,y,z=v;return (z,y,-x)

def rotations(shape):
    start=norm(shape);seen={start};todo=[start]
    while todo:
        a=todo.pop()
        for move in (mx,my):
            b=norm(move(p) for p in a)
            if b not in seen:seen.add(b);todo.append(b)
    return seen

def canonical(shape):return min(rotations(shape))
def connected(shape):
    cells=set(map(tuple,shape));todo=[next(iter(cells))];seen=set(todo)
    while todo:
        p=todo.pop()
        for a in range(3):
            for s in (-1,1):
                q=list(p);q[a]+=s;q=tuple(q)
                if q in cells and q not in seen:seen.add(q);todo.append(q)
    return len(seen)==len(cells)

def poses(shape,target):
    target=set(target);found=set()
    for ori in rotations(shape):
        anchor=ori[0]
        for cell in target:
            offset=tuple(cell[i]-anchor[i] for i in range(3))
            placed=tuple(sorted(tuple(p[i]+offset[i] for i in range(3)) for p in ori))
            if set(placed)<=target:found.add(placed)
    return found

def can_tile(pieces,target):
    target=set(map(tuple,target))
    if sum(map(len,pieces))!=len(target):return False
    pp=[[(frozenset(p),p) for p in poses(piece,target)] for piece in pieces]
    if any(not a for a in pp):return False
    order=sorted(range(len(pieces)),key=lambda i:len(pp[i]))
    def go(k,remaining):
        if k==len(order):return not remaining
        for cells,_ in pp[order[k]]:
            if cells<=remaining and go(k+1,remaining-cells):return True
        return False
    return go(0,frozenset(target))

def ray_hits(origin,direction,cell):
    lo,hi=0.00001,1e9
    for i in range(3):
        # all three direction components are +-1
        a=(cell[i]-origin[i])/direction[i];b=(cell[i]+1-origin[i])/direction[i]
        lo=max(lo,min(a,b));hi=min(hi,max(a,b))
    return hi>lo+1e-8

def hidden_cells(shape):
    shape=norm(shape);cells=set(shape);hidden=[]
    for cell in shape:
        visible=False
        for direction in ((1,1,1),(-1,-1,1)):
            for a in range(3):
                sign=direction[a]
                neighbor=tuple(cell[i]+(sign if i==a else 0) for i in range(3))
                if neighbor in cells:continue
                others=[i for i in range(3) if i!=a]
                for u,v in product((.1,.3,.5,.7,.9),repeat=2):
                    pt=[cell[i]+.5 for i in range(3)]
                    pt[a]=cell[a]+(1 if sign==1 else 0)
                    pt[others[0]]=cell[others[0]]+u;pt[others[1]]=cell[others[1]]+v
                    if not any(ray_hits(pt,direction,other) for other in cells if other!=cell):visible=True;break
                if visible:break
            if visible:break
        if not visible:hidden.append(cell)
    return hidden

def degrees(shape):
    cells=set(shape)
    return sorted(sum(sum(abs(p[i]-q[i]) for i in range(3))==1 for q in cells) for p in cells)

def residuals(pieces,target):
    target=set(target);pp=[list(poses(p,target)) for p in pieces]
    result=[]
    for chosen in product(*pp):
        occupied=set().union(*map(set,chosen))
        if sum(map(len,chosen))==len(occupied):result.append(target-occupied)
    return result

def semantic_audit():
    notes=[]
    for n in (1,2,7):
        q=QUESTIONS[n-1];r=[s for s in residuals(q['pieces'],q['target']) if s and connected(s)]
        assert len({canonical(s) for s in r})==1
        good=q['options']['ABCD'.index(q['answer'])]
        bad=q['options'][1 if n==2 else 0]
        assert canonical(bad)==canonical([(-x,y,z) for x,y,z in good])!=canonical(good)
        notes.append({'n':n,'checked':'unique connected residual rotation class and actual mirror distractor'})
    q=QUESTIONS[2]
    assert degrees(q['pieces'][0])==[1,1,1,2,2,3] and degrees(q['pieces'][1])==[1,1,2,2,2,2]
    assert all(not any(connected(r) for r in residuals(q['pieces'][:1],q['options'][i])) for i in (0,1))
    r=residuals(q['pieces'][:1],q['options'][2]);assert len(r)==1 and max(degrees(r[0]))==3
    assert '两个部件都是' not in ''.join(q['analysis']) and '两条折链' not in ''.join(q['analysis'])
    notes.append({'n':3,'checked':'A/B all remainders disconnected; C sole placement leaves branching remainder; corrected given A branching and given B chain'})
    q=QUESTIONS[3]
    for i in (0,3):
        r=[s for s in residuals(q['pieces'][:1],q['options'][i]) if connected(s)]
        assert r and all(degrees(s)==[1,1,1,3] for s in r)
    r=[s for s in residuals(q['pieces'][:1],q['options'][2]) if connected(s)]
    assert r and all(min(max(p[a] for p in norm(s))+1 for a in range(3))==1 for s in r)
    notes.append({'n':4,'checked':'A/D connected remainders branch; C remainder planar'})
    q=QUESTIONS[4]
    r=[s for s in residuals(q['pieces'],q['target']) if connected(s)]
    assert len({canonical(s) for s in r})==2
    assert {tuple(degrees(s)) for s in r}=={(2,2,2,2),(1,1,2,2)}
    notes.append({'n':5,'checked':'exactly two connected remainder classes square and planar skew chain'})
    q=QUESTIONS[5]
    for i in (0,1,3):
        r=[s for s in residuals(q['pieces'][:2],q['options'][i]) if connected(s)]
        assert r and all(max(degrees(s))==2 for s in r)
    assert degrees(q['pieces'][2])==[1,1,1,3]
    notes.append({'n':6,'checked':'A/B/D cannot leave degree-three branch needed by C component'})
    q=QUESTIONS[7]
    assert not any(connected(r) for r in residuals(q['pieces'][:1],q['options'][3]))
    notes.append({'n':8,'checked':'D every full first-component placement disconnects remainder'})
    q=QUESTIONS[8]
    r=[s for s in residuals(q['pieces'],q['target']) if connected(s)]
    assert len({canonical(s) for s in r})==2
    assert {tuple(degrees(s)) for s in r}=={(1,1,2,2,3,3),(1,2,2,2,2,3)}
    assert canonical(q['options'][0])==canonical([(-x,y,z) for x,y,z in q['options'][2]])!=canonical(q['options'][2])
    notes.append({'n':9,'checked':'final revised model two connected remainder classes and mirror A of C'})
    q=QUESTIONS[9]
    assert not residuals(q['pieces'][:2],q['options'][0])
    notes.append({'n':10,'checked':'A even first two components have no nonoverlapping placements'})
    assert all(len(q['analysis'])>=2 for q in QUESTIONS)
    return notes

def main():
    assert len(rotations(((0,0,0),(1,0,0),(0,2,0),(0,0,3))))==24
    report=[];issues=[]
    for q in QUESTIONS:
        n=q['n'];pieces=q['pieces'];opts=q['options'];result=[]
        for option in opts:
            result.append(can_tile(pieces+[option],q['target']) if q['mode']=='fill' else can_tile(pieces,option))
        expected=[not b if q['except'] else b for b in result]
        answer='ABCD'[expected.index(True)] if sum(expected)==1 else None
        assert answer==q['answer'],(n,result,answer,q['answer'])
        assert len(set(map(len,opts)))==1,(n,'volumes differ')
        assert len({canonical(p) for p in opts})==4,(n,'equivalent options')
        target_shapes=[q['target']] if q['mode']=='fill' else opts
        assert all(min(max(p[i] for p in norm(s))+1 for i in range(3))>1 for s in target_shapes),(n,'flat target')
        for name,p in [(f'piece{i+1}',p) for i,p in enumerate(pieces)]+[(f'option{c}',p) for c,p in zip('ABCD',opts)]:
            assert len(set(p))==len(p) and connected(p),(n,name,'nonconnected')
        solution=list(map(lambda p:set(map(tuple,p)),q['solution']))
        solution_for=q.get('solution_for',q['answer'])
        components=pieces+([opts['ABCD'.index(solution_for)]] if q['mode']=='fill' else [])
        target=set(q['target'] if q['mode']=='fill' else opts['ABCD'.index(solution_for)])
        assert len(solution)==len(components),(n,'solution count')
        assert all(canonical(a)==canonical(b) for a,b in zip(components,solution)),(n,'solution reflection')
        assert sum(map(len,solution))==len(set.union(*solution))==len(target),(n,'overlap')
        assert set.union(*solution)==target,(n,'wrong target')
        visuals=[]
        for name,p in [(f'piece{i+1}',p) for i,p in enumerate(pieces)]+[(f'option{c}',p) for c,p in zip('ABCD',opts)]+([('target',q['target'])] if q['mode']=='fill' else []):
            hidden=hidden_cells(p)
            if hidden:
                cells=set(norm(p));dim=[max(c[i] for c in cells)+1 for i in range(3)]
                invisible_empty=[c for c in product(*(range(d) for d in dim)) if c not in cells and c in hidden_cells(cells|{c})]
                assert not invisible_empty,(n,name,'hidden occupied cell could trade with hidden empty cell')
                assert len(hidden)==1
                visuals.append({'shape':name,'fully_hidden_cells':hidden,'invisible_empty_cells':invisible_empty,
                                'resolution':'total block count shown uniformly in every shape title; full rectangular targets also dimensioned'})
        row={'n':n,'options_can_tile':dict(zip('ABCD',result)),'answer':answer,'solution_for':solution_for,
             'volumes_equal':True,'options_not_rotation_equivalent':True,'connected_all_shapes':True,
             'targets_span_three_axes':True,'solution_verified':True,'dual_top_view_hidden_cells':visuals}
        report.append(row)
        if visuals:issues.append({'n':n,'type':'hidden_cells_in_dual_views','detail':visuals})
    assert '共{len(shape)}块' in (ROOT/'draw.py').read_text(encoding='utf-8')
    semantic=semantic_audit()
    out={'passed_math':True,'passed_semantics':True,'method':'BFS quarter-turn closure and anchor-alignment tiling search independent of solver.py',
         'puzzles_sha256':hashlib.sha256((ROOT/'puzzles.py').read_bytes()).hexdigest(),'questions':report,'visual_risks_resolved':issues,
         'required_visual_fix_present_in_renderer':True,'semantic_checks':semantic,
         'manual_image_review':'All ten initial full question diagrams viewed; frames, two viewpoints and option mapping clear. Final document raster QA remains separate.'}
    (ROOT/'independent_review.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps(out,ensure_ascii=False,indent=2))

if __name__=='__main__':main()
